from events import iterate, read_events


class FakeFile:
    """File-like object that counts how much of it has been read."""

    def __init__(self, lines):
        self._lines = list(lines)
        self._i = 0
        self.lines_read = 0
        self.read_everything = False

    def readline(self):
        if self._i >= len(self._lines):
            return ""
        line = self._lines[self._i]
        self._i += 1
        self.lines_read += 1
        return line + "\n"

    def __iter__(self):
        return self

    def __next__(self):
        line = self.readline()
        if line == "":
            raise StopIteration
        return line

    def read(self):
        self.read_everything = True
        rest = self._lines[self._i:]
        self._i = len(self._lines)
        self.lines_read = len(self._lines)
        return "".join(x + "\n" for x in rest)

    def readlines(self):
        return [x + "\n" for x in self.read().splitlines()]


def test_iterate_reads_one_line_at_a_time():
    fake = FakeFile(f"INFO|msg {i}" for i in range(10000))
    it = iterate(fake)
    first = next(it)
    assert first == {"level": "INFO", "message": "msg 0"}
    assert fake.lines_read <= 2, (
        f"read {fake.lines_read} lines to yield one event")
    assert not fake.read_everything, "iterate slurped the whole file"


def test_iterate_takes_paths_and_read_events_still_works(tmp_path):
    p = tmp_path / "a.log"
    p.write_text("ERROR|boom\nINFO|ok\n")
    assert list(iterate(str(p))) == [
        {"level": "ERROR", "message": "boom"},
        {"level": "INFO", "message": "ok"},
    ]
    assert read_events(str(p)) == [
        {"level": "ERROR", "message": "boom"},
        {"level": "INFO", "message": "ok"},
    ]

