def test_filtered_iteration_stays_lazy():
    lines = []
    for i in range(5000):
        lines.append(f"ERROR|e{i}" if i % 50 == 0 else f"INFO|i{i}")
    fake = FakeFile(lines)
    got = []
    for event in iterate(fake, level="ERROR"):
        got.append(event)
        if len(got) == 3:
            break
    assert [e["message"] for e in got] == ["e0", "e50", "e100"]
    assert fake.lines_read < 500, (
        f"read {fake.lines_read} lines to find three errors")
    assert not fake.read_everything
